init_define_import_meta_env();
import { createClient } from "npm:@supabase/supabase-js@^2.89.0";
function runtimeEnv(name) {
  const runtime = globalThis;
  return runtime.Deno?.env?.get?.(name) ?? runtime.process?.env?.[name];
}
function configuredEnv(names) {
  for (const name of names) {
    const value = runtimeEnv(name)?.trim();
    if (value) return value;
  }
  return void 0;
}
function supabaseProjectUrl() {
  const url = configuredEnv(["SUPABASE_URL", "VITE_SUPABASE_URL"]);
  if (!url) throw new Error("SUPABASE_URL (or VITE_SUPABASE_URL) is required");
  return url;
}
function supabasePublishableKey() {
  const direct = configuredEnv([
    "SUPABASE_PUBLISHABLE_KEY",
    "VITE_SUPABASE_PUBLISHABLE_KEY"
  ]);
  if (direct) return direct;
  const keyset = runtimeEnv("SUPABASE_PUBLISHABLE_KEYS");
  if (keyset) {
    try {
      const parsed = JSON.parse(keyset);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const keys = parsed;
        const key = [keys.default, ...Object.values(keys)].find((v) => typeof v === "string" && v.trim().startsWith("sb_publishable_"))?.trim();
        if (key) return key;
      }
    } catch {
    }
  }
  const legacy = configuredEnv(["SUPABASE_ANON_KEY", "VITE_SUPABASE_ANON_KEY"]);
  if (legacy) return legacy;
  throw new Error("SUPABASE_PUBLISHABLE_KEY, SUPABASE_PUBLISHABLE_KEYS, or SUPABASE_ANON_KEY is required");
}
function supabaseAnon() {
  return createClient(supabaseProjectUrl(), supabasePublishableKey(), {
    auth: { persistSession: false, autoRefreshToken: false }
  });
}

// src/lib/mcp/tools/get-leaderboard.ts
var get_leaderboard_default = defineTool4({
  name: "get_leaderboard",
  title: "Get leaderboard",
  description: "Read the public prediction leaderboard for a period (24h, 7d, 30d or all): wallet, bets, wins, losses, win rate, staked, payout and profit in $BLOOM.",
  inputSchema: {
    period: z3.enum(["24h", "7d", "30d", "all"]).describe("Time window for the ranking."),
    limit: z3.number().int().min(1).max(50).optional().describe("How many rows to return (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
  handler: async ({ period, limit }) => {
    const supabase = supabaseAnon();
    const { data, error } = await supabase.rpc("get_leaderboard", { period });
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    const rows = (data ?? []).slice(0, limit ?? 10).map((row, i) => ({
      rank: i + 1,
      wallet: row.wallet_address,
      totalBets: row.total_bets,
      totalWins: row.total_wins,
      totalLosses: row.total_losses,
      winRatePercent: Number(row.win_rate ?? 0),
      stakedBloom: Number(row.staked ?? 0),
      payoutBloom: Number(row.payout ?? 0),
      profitBloom: Number(row.profit ?? 0)
    }));
    return {
      content: [{ type: "text", text: JSON.stringify({ period, rows }, null, 2) }],
      structuredContent: { period, rows }
    };
  }
});

