// src/lib/mcp/tools/prepare-bet.ts
init_define_import_meta_env();
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z4 } from "npm:zod@^3.25.76";
import { encodeFunctionData, parseUnits } from "npm:viem@^2.43.3";
init_BloomBetting();
var prepare_bet_default = defineTool6({
  name: "prepare_bet",
  title: "Prepare a prediction transaction",
  description: "Build the unsigned Base transaction(s) needed to predict UP or DOWN on the current ETH round with $BLOOM. Returns an optional ERC-20 approval call plus the placeBet call, to be signed and sent by the caller's own wallet. Nothing is signed or submitted here.",
  inputSchema: {
    address: z4.string().regex(/^0x[a-fA-F0-9]{40}$/).describe("The wallet address that will sign and send the transaction."),
    direction: z4.enum(["up", "down"]).describe("Predicted ETH direction for this round."),
    amountBloom: z4.number().positive().describe("Stake size in whole $BLOOM tokens (not wei).")
  },
  annotations: { readOnlyHint: true, openWorldHint: true },
  handler: async ({ address, direction, amountBloom }) => {
    const amountWei = parseUnits(String(amountBloom), 18);
    const [bettingOpen, round, minimumStake, balance, allowance] = await Promise.all([
      readBetting("isBettingOpen"),
      readBetting("getCurrentRound"),
      readBetting("minimumStake"),
      readToken("balanceOf", [address]),
      readToken("allowance", [address, BLOOM_BETTING_ADDRESS])
    ]);
    const roundId = Number(round.roundId);
    const alreadyBet = await readBetting("hasUserBetInRound", [round.roundId, address]);
    const problems = [];
    if (!bettingOpen) problems.push("Betting is closed for the current round.");
    if (alreadyBet) problems.push(`This wallet already placed a bet in round ${roundId}.`);
    if (amountWei < minimumStake)
      problems.push(`Stake is below the minimum of ${formatBloom(minimumStake)} $BLOOM.`);
    if (balance < amountWei)
      problems.push(`Wallet holds only ${formatBloom(balance)} $BLOOM.`);
    if (problems.length > 0) {
      return {
        content: [{ type: "text", text: problems.join(" ") }],
        isError: true
      };
    }
    const transactions = [];
    if (allowance < amountWei) {
      transactions.push({
        step: "approve",
        chainId: 8453,
        to: BLOOM_TOKEN_ADDRESS,
        data: encodeFunctionData({
          abi: ERC20_ABI,
          functionName: "approve",
          args: [BLOOM_BETTING_ADDRESS, amountWei]
        }),
        value: "0"
      });
    }
    transactions.push({
      step: "placeBet",
      chainId: 8453,
      to: BLOOM_BETTING_ADDRESS,
      data: encodeFunctionData({
        abi: BLOOM_BETTING_ABI,
        functionName: "placeBet",
        args: [direction === "up" ? 1 : 2, amountWei]
      }),
      value: "0"
    });
    const data = {
      network: "base",
      chainId: 8453,
      roundId,
      direction,
      amountBloom,
      amountWei: amountWei.toString(),
      potentialPayoutBloom: amountBloom * 2,
      secondsRemaining: Number(round.endTime) - Math.floor(Date.now() / 1e3),
      transactions,
      note: "Sign and broadcast these transactions in order from the given wallet. Draws count as a loss; payouts are 2x."
    };
    return {
      content: [{ type: "text", text: JSON.stringify(data, null, 2) }],
      structuredContent: data
    };
  }
});

